/* Casos fictícios didáticos do PsicoMoodle: decisões com feedback, sem gabaritos de diagnóstico. */
window.PSICO_CASES={"familia":[{"id":"luto-familiar","title":"Luto e reorganização de papéis","area":"Luto e ciclo vital","intro":"Após a morte da avó, três integrantes da família lidam de maneiras diferentes com a perda. Uma pessoa assumiu todas as tarefas, outra ficou retraída e uma adolescente evita falar do assunto.","stages":[{"prompt":"Qual seria uma primeira leitura mais cuidadosa?","choices":[{"label":"Priorizar a estabilização da rotina e avaliar a adaptação pelos papéis que cada membro consegue manter.","outcome":"A organização prática recebe atenção, mas pode encobrir necessidades afetivas diferentes.","reason":"Retomada de tarefas é relevante no luto, porém funcionamento instrumental não substitui compreensão relacional da perda.","best":false},{"label":"Conduzir a avaliação pela identificação de fases de luto individuais, comparando os ritmos de cada familiar.","outcome":"O sofrimento é descrito em etapas, dificultando perceber demandas prelacionares e reorganização dos vínculos.","reason":"Etapas podem servir a discussões históricas, mas não devem funcionar como calendário normativo da experiência de cada pessoa.","best":false},{"label":"Investigar como cada integrante vive a perda e como os papéis se reorganizaram.","outcome":"A família começa a nomear experiências diferentes e percebe a sobrecarga de quem assumiu o cuidado.","reason":"O luto não tem sequência emocional obrigatória; a perspectiva sistêmica considera vínculos e tarefas.","best":true}]},{"prompt":"Depois, a pessoa sobrecarregada começa a faltar ao trabalho. Como aprofundar o cuidado?","choices":[{"label":"Mapear redes de apoio, combinar responsabilidades e acolher limites individuais.","outcome":"As tarefas deixam de depender de uma única pessoa e o diálogo sobre necessidades se amplia.","reason":"A intervenção pode integrar recursos externos e acordos práticos sem padronizar a maneira de sofrer.","best":true},{"label":"Distribuir tarefas de acordo com quem demonstra maior estabilidade emocional, mantendo as funções já assumidas.","outcome":"O funcionamento imediato melhora, mas pode consolidar a sobrecarga de quem aparenta lidar melhor com a perda.","reason":"A aparência de estabilidade não implica disponibilidade ilimitada; intervenção sistêmica revisa distribuição e apoio.","best":false},{"label":"Priorizar conversas individuais sobre a expressão emocional de cada um, deixando os acordos práticos para depois.","outcome":"Experiências pessoais são acolhidas, mas a pressão concreta do cuidado e do trabalho permanece.","reason":"A escuta individual é valiosa, mas a sobrecarga também exige negociação de responsabilidades e rede de apoio.","best":false}]}],"wrapUp":"O caso envolve luto, reorganização de responsabilidades e cuidado com diferenças na experiência da perda."},{"id":"alcool-papeis","title":"Dependência química e papéis familiares","area":"Dependência química","intro":"Um adulto apresenta uso problemático de álcool. Um adolescente passou a cuidar de tarefas domésticas de adultos, enquanto os outros familiares evitam conversar sobre o problema.","stages":[{"prompt":"Qual hipótese inicial é mais fundamentada?","choices":[{"label":"Concentrar a avaliação nos padrões de comunicação familiar, para então deduzir como eles mantêm o uso de álcool.","outcome":"A família identifica interações, mas os fatores de saúde e as necessidades do adolescente ficam subordinados.","reason":"A visão sistêmica investiga padrões relacionais sem reduzir a dependência química a uma causalidade familiar única.","best":false},{"label":"Examinar distribuição de tarefas, proteção do adolescente e acesso a cuidado especializado.","outcome":"A sobrecarga passa a ser reconhecida e surgem possibilidades de reorganização.","reason":"Uso problemático exige atenção clínica e social, sem atribuir culpa moral automática à família.","best":true},{"label":"Avaliar inicialmente a motivação do adulto para tratamento e incluir os outros integrantes somente após adesão.","outcome":"O plano se volta ao usuário, enquanto o adolescente continua exposto à sobrecarga.","reason":"Cuidado do adulto importa, mas proteção dos demais familiares não precisa aguardar início do tratamento.","best":false}]},{"prompt":"O adolescente relata exaustão e medo de procurar ajuda. Qual seria o próximo passo?","choices":[{"label":"Organizar a comunicação do adolescente com o adulto para que ele consiga negociar uma redução do consumo.","outcome":"O adolescente participa ativamente, mas assume responsabilidade que não lhe cabe pelo comportamento do adulto.","reason":"Pode haver diálogo familiar seguro, porém a responsabilidade pelo tratamento deve permanecer com adultos e serviços competentes.","best":false},{"label":"Priorizar encaminhamento do adulto a tratamento e revisar a situação do adolescente apenas após os primeiros retornos.","outcome":"O atendimento do adulto avança, mas a insegurança imediata do adolescente fica sem avaliação.","reason":"Demandas de proteção e apoio ao adolescente devem ser investigadas paralelamente, não somente após adesão do adulto.","best":false},{"label":"Investigar segurança, envolver rede de apoio e orientar acesso a serviços conforme a demanda.","outcome":"O adolescente encontra adultos de referência e as responsabilidades podem ser redistribuídas.","reason":"A prioridade inclui proteção, limites dos papéis e acolhimento sem exposição desnecessária.","best":true}]}],"wrapUp":"O raciocínio sistêmico conecta saúde, sobrecarga e rede de apoio sem responsabilizar quem sofre pelo comportamento alheio."},{"id":"violencia-protecao","title":"Violência intrafamiliar e proteção","area":"Violência e ética","intro":"Uma criança conta a uma psicóloga da escola que tem medo de voltar para casa porque um adulto costuma agredi-la. Outro familiar pede que a profissional não comunique a situação.","stages":[{"prompt":"Qual é a prioridade da atuação?","choices":[{"label":"Acolher sem interrogatórios repetidos, avaliar risco e seguir os protocolos de proteção.","outcome":"A criança recebe escuta segura e a rede de proteção pode ser acionada.","reason":"Em situação de possível violência, segurança e deveres legais têm prioridade sobre neutralidade aparente.","best":true},{"label":"Realizar uma reunião sistêmica com familiares disponíveis para reconstruir a sequência do conflito antes dos encaminhamentos.","outcome":"A reconstrução relacional começa, mas pode expor a vítima ao agressor e ampliar o risco.","reason":"Em suspeita de violência, intervenção conjunta depende de avaliação prévia de segurança e assimetria de poder.","best":false},{"label":"Iniciar uma investigação clínica aprofundada do relato para confirmar a consistência antes de ativar a rede de proteção.","outcome":"A coleta se amplia, mas o cuidado protetivo é condicionado a repetição potencialmente revitimizante.","reason":"A escuta deve ser protegida e suficiente para encaminhamento adequado; não cabe exigir comprovação clínica exaustiva como condição inicial.","best":false}]},{"prompt":"Surge a proposta de terapia familiar conjunta imediatamente. O que considerar?","choices":[{"label":"Utilizar a terapia de casal ou família para negociar responsabilidades, desde que todos concordem em participar.","outcome":"A adesão formal existe, mas a assimetria de poder pode impedir consentimento realmente livre.","reason":"Consentimento não elimina riscos; segurança e medidas protetivas precisam anteceder qualquer encontro conjunto.","best":false},{"label":"Avaliar segurança, assimetria de poder e condições de participação antes de qualquer encontro conjunto.","outcome":"A equipe evita colocar vítima e possível agressor numa situação insegura.","reason":"Interdependência sistêmica não significa responsabilidade igual nem substitui medidas protetivas.","best":true},{"label":"Trabalhar primeiro padrões intergeracionais da família e reconsiderar o risco após compreender sua origem.","outcome":"A história oferece contexto, mas as necessidades imediatas de proteção são postergadas.","reason":"Explicação sistêmica da história não substitui avaliação atual de risco nem atribuição de responsabilidade.","best":false}]}],"wrapUp":"Analisar violência exige proteção, responsabilidade, escuta cuidadosa e trabalho com redes."}],"avaliacao":[{"id":"devolutiva-adolescente","title":"Devolutiva com adolescente","area":"Entrevista e sigilo","intro":"Uma adolescente passou por avaliação psicológica. Os responsáveis solicitam acesso integral às falas pessoais que compartilhou ao longo das entrevistas.","stages":[{"prompt":"Como preparar a devolutiva?","choices":[{"label":"Organizar informações relevantes à demanda e discutir limites de confidencialidade de modo compreensível.","outcome":"A adolescente é respeitada e os responsáveis compreendem o necessário para o cuidado.","reason":"Devolutiva é comunicação técnica, com pertinência e proteção de informações sensíveis.","best":true},{"label":"Apresentar primeiro um resumo uniforme aos responsáveis e depois reservar a discussão dos pontos íntimos com o adolescente.","outcome":"A estrutura agiliza a reunião, mas pode divulgar informações cuja finalidade ainda não foi delimitada.","reason":"O formato da devolutiva não substitui avaliação individualizada de sigilo, pertinência e direitos de adolescentes.","best":false},{"label":"Organizar uma devolutiva exclusivamente para o adolescente e encaminhar aos responsáveis somente o documento final.","outcome":"A autonomia é valorizada, mas podem faltar orientações de cuidado que exigem participação responsável.","reason":"Confidencialidade não é isolamento total; os limites de informação devem considerar desenvolvimento, proteção e finalidade.","best":false}]},{"prompt":"Na conversa, os responsáveis pedem um diagnóstico que os dados não sustentam. O que fazer?","choices":[{"label":"Formular uma hipótese provisória para atender à demanda, desde que a família seja informada de que ainda faltam dados.","outcome":"A incerteza é mencionada, mas a terminologia diagnóstica pode ganhar peso desproporcional.","reason":"Hipóteses devem ser delimitadas tecnicamente; não se produz um diagnóstico a pedido sem base suficiente.","best":false},{"label":"Explicar limites e resultados com linguagem clara, registrando recomendações proporcionais.","outcome":"A família recebe orientação possível sem conclusão indevida.","reason":"O documento e a devolutiva precisam corresponder às evidências produzidas.","best":true},{"label":"Oferecer recomendações práticas sem discutir os dados inconclusivos, para não aumentar a ansiedade dos responsáveis.","outcome":"As orientações ficam acessíveis, mas a comunicação omite limites relevantes da avaliação.","reason":"Devolutiva acessível também precisa ser precisa quanto às evidências, incertezas e alcance das conclusões.","best":false}]}],"wrapUp":"A questão não é revelar tudo ou ocultar tudo, mas comunicar o que é tecnicamente fundamentado e eticamente pertinente."},{"id":"hospital-paciente","title":"Avaliação no contexto hospitalar","area":"Hospital e contexto","intro":"Uma pessoa internada sente fadiga intensa e dificuldade para responder a instrumentos longos. A equipe pede um resultado psicológico imediato para planejar o cuidado.","stages":[{"prompt":"Como conduzir a avaliação?","choices":[{"label":"Preservar a bateria padronizada e interpretar o desempenho considerando posteriormente os efeitos da dor e da fadiga.","outcome":"A comparabilidade formal é privilegiada, mas condições de aplicação podem invalidar a própria interpretação.","reason":"Condições clínicas podem exigir seleção, adaptação permitida ou adiamento do instrumento, antes de inferir resultados.","best":false},{"label":"Realizar inicialmente entrevista breve e observação, deixando a definição da demanda com a equipe para a devolutiva.","outcome":"O contato com o paciente ocorre, mas a avaliação perde a delimitação compartilhada de objetivos.","reason":"No hospital, a finalidade e a possibilidade de aplicação precisam ser discutidas desde a escolha do método.","best":false},{"label":"Adequar métodos às condições clínicas e esclarecer o objetivo com a equipe.","outcome":"O processo respeita limitações e produz dados mais interpretáveis.","reason":"Demanda, estado clínico, consentimento e adequação dos instrumentos orientam a escolha.","best":true}]},{"prompt":"Os dados são inconclusivos, mas a equipe insiste em um parecer definitivo. Qual resposta é adequada?","choices":[{"label":"Comunicar achados, limitações e necessidade de nova avaliação quando cabível.","outcome":"O cuidado pode ser planejado considerando a incerteza real.","reason":"Comunicação honesta favorece decisões e evita excesso de confiança.","best":true},{"label":"Relatar o resultado como hipótese provável para apoiar decisões imediatas, reservando as limitações para registro interno.","outcome":"A equipe recebe direção de trabalho, mas pode entender a inferência como conclusão estabilizada.","reason":"Hipóteses podem ser úteis, desde que incertezas e limites sejam explicitados no mesmo compartilhamento.","best":false},{"label":"Solicitar avaliação complementar e restringir a devolutiva a recomendações provisórias que não exijam interpretação dos achados atuais.","outcome":"A cautela protege decisões, mas pode ocultar achados parciais relevantes para o manejo da equipe.","reason":"É possível comunicar achados parciais e limites, relacionando necessidade de reavaliação quando pertinente.","best":false}]}],"wrapUp":"Em ambiente hospitalar, a qualidade da avaliação depende da adequação ao paciente e à demanda."},{"id":"forense-documento","title":"Documento solicitado pela Justiça","area":"Contexto forense","intro":"Uma psicóloga recebe solicitação judicial com perguntas específicas e, simultaneamente, pressão informal de uma das partes para redigir conclusão favorável.","stages":[{"prompt":"Qual é a postura mais adequada?","choices":[{"label":"Delimitar finalidade, papel profissional, métodos e independência técnica.","outcome":"As informações ficam relacionadas à demanda e menos suscetíveis a pressões externas.","reason":"A atuação forense exige fundamentação, clareza e imparcialidade metodológica.","best":true},{"label":"Priorizar a definição do instrumento de avaliação e, a partir dele, estabelecer quais quesitos podem ser respondidos.","outcome":"O método orienta a demanda, invertendo a sequência de escolha técnica.","reason":"Em perícia, método e fontes devem ser selecionados a partir dos quesitos e do papel assumido, não o contrário.","best":false},{"label":"Organizar a entrevista em torno da narrativa da parte solicitante, usando documentos complementares para verificar coerência.","outcome":"O relato inicial estrutura a investigação e pode enviesar o peso de evidências divergentes.","reason":"A independência técnica requer avaliar fontes múltiplas sem transformar a versão inicial em eixo privilegiado.","best":false}]},{"prompt":"Ao terminar, falta informação relevante para responder uma pergunta. O que redigir?","choices":[{"label":"Apresentar resposta probabilística sem detalhar lacunas para preservar objetividade e concisão do documento.","outcome":"A conclusão parece clara, mas o leitor não consegue avaliar os limites de inferência.","reason":"A incerteza pode ser expressa com precisão, mas deve vir acompanhada das bases e lacunas metodológicas.","best":false},{"label":"Explicitar o que foi e não foi possível concluir e indicar limites.","outcome":"O destinatário compreende a extensão real dos achados.","reason":"A honestidade técnica é obrigatória mesmo quando a resposta não atende expectativas.","best":true},{"label":"Responder ao quesito com a conclusão mais compatível com os dados disponíveis, deslocando as limitações para o histórico técnico.","outcome":"A resposta objetiva ganha destaque, mas as ressalvas se tornam pouco visíveis para quem decide.","reason":"Limites precisam acompanhar conclusões quando condicionam diretamente o que pode ser afirmado.","best":false}]}],"wrapUp":"O caso exercita independência e limites dos documentos psicológicos, sem substituir as normas profissionais."},{"id":"organizacao-car-dinamica-p3","title":"Entrevista por competências e dinâmica de grupo","area":"Avaliação organizacional · P3","intro":"Uma empresa define competências relevantes para uma função e solicita entrevistas por competências e uma dinâmica de grupo. Um candidato relata o êxito de uma equipe, sem esclarecer sua contribuição individual.","stages":[{"prompt":"Qual atitude torna a entrevista por competências mais fundamentada?","choices":[{"label":"Tomar o sucesso geral da equipe como evidência principal da competência do candidato, pois o resultado coletivo também expressa sua participação.","outcome":"O resultado é valorizado, mas não se identifica a contribuição real do candidato.","reason":"No modelo CAR, o resultado deve ser relacionado ao contexto e às ações efetivamente realizadas pela pessoa avaliada.","best":false},{"label":"Solicitar que o candidato descreva o contexto, especifique as próprias ações e explique os resultados e aprendizados da experiência apresentada.","outcome":"O relato permite examinar o que ocorreu, o que o candidato realizou e quais foram os desfechos.","reason":"O modelo CAR diferencia Contexto, Ação e Resultado. Experiências passadas fornecem indícios, mas não garantem desempenho futuro.","best":true},{"label":"Substituir o relato anterior por uma situação hipotética, pois as competências futuras podem ser avaliadas sem investigar ações executadas no passado.","outcome":"O entrevistador obtém possibilidades de resposta, mas deixa de examinar comportamentos efetivamente realizados.","reason":"A entrevista por competências pode utilizar perguntas complementares, mas sua premissa principal envolve exemplos de experiências concretas.","best":false}]},{"prompt":"Na dinâmica, uma candidata participa pouco verbalmente, mas ajuda o grupo a organizar decisões. Como interpretar essa observação?","choices":[{"label":"Registrar que a candidata demonstra baixa iniciativa, uma vez que a participação verbal frequente é o critério mais direto para reconhecer liderança.","outcome":"A avaliação privilegia a quantidade de falas e deixa de considerar contribuições observáveis.","reason":"A participação deve ser analisada segundo competências previamente definidas, sem reduzir iniciativa à frequência com que alguém fala.","best":false},{"label":"Concluir que a candidata tem competência de liderança plenamente comprovada, já que sua contribuição foi observada em uma atividade estruturada.","outcome":"O comportamento observado é relevante, mas uma única dinâmica não confirma uma competência em todas as situações.","reason":"A conclusão depende de integração de informações, critérios, oportunidades de participação e condições da atividade.","best":false},{"label":"Descrever a organização das decisões como comportamento observável e relacioná-la aos critérios da função, considerando os limites daquela situação.","outcome":"A análise utiliza evidências da dinâmica sem transformá-las em traço permanente da pessoa.","reason":"Dinâmicas de grupo exigem observação de comportamentos, critérios e contextualização; não são diagnósticos informais de personalidade.","best":true}]}],"wrapUp":"Este caso reúne os principais conteúdos organizacionais da P3: entrevista por competências, modelo CAR e observação contextualizada em dinâmicas."},{"id":"protig-acolhimento-p3","title":"Acolhimento e avaliação no PROTIG","area":"Pacientes trans · P3","intro":"Uma pessoa trans procura atendimento em equipe multiprofissional e relata expectativas pessoais sobre o cuidado. A equipe precisa compreender a demanda sem presumir que exista um único percurso adequado.","stages":[{"prompt":"Qual postura corresponde melhor à compreensão global da demanda na etapa diagnóstica?","choices":[{"label":"Começar pela confirmação de uma hipótese clínica ligada à identidade de gênero, para depois investigar necessidades subjetivas e sociais relacionadas ao cuidado.","outcome":"O processo parte de uma hipótese predefinida e restringe a escuta das necessidades apresentadas.","reason":"A identidade de gênero não deve ser tratada como patologia; a avaliação busca compreender trajetória, demandas e objetivos individuais.","best":false},{"label":"Investigar história pessoal, contexto de vida, expectativas e necessidades de saúde, com escuta respeitosa e integração das contribuições da equipe.","outcome":"A equipe compreende melhor a demanda sem pressupor um procedimento obrigatório.","reason":"A etapa diagnóstica deve ser abrangente, individualizada, não discriminatória e voltada às necessidades da pessoa.","best":true},{"label":"Definir inicialmente o procedimento mais comum do serviço, utilizando a entrevista para identificar fatores que poderiam impedir sua realização.","outcome":"A decisão precede a compreensão completa da demanda e pode ignorar objetivos individuais.","reason":"O planejamento do cuidado depende da compreensão da pessoa, de suas expectativas e das possibilidades de acompanhamento.","best":false}]},{"prompt":"A pessoa informa que não deseja seguir todas as etapas esperadas por outros usuários do serviço. Como proceder?","choices":[{"label":"Respeitar a decisão, esclarecer opções e limites do serviço e construir, com consentimento, um acompanhamento compatível com as necessidades apresentadas.","outcome":"A autonomia e a individualidade orientam o cuidado, sem dispensar avaliação e informações adequadas.","reason":"A assistência deve apoiar decisões informadas e não pressupor que toda pessoa trans busque o mesmo tipo de intervenção.","best":true},{"label":"Explicar que a etapa diagnóstica exige uma trajetória padronizada para garantir tratamento igualitário, ainda que os objetivos pessoais sejam distintos.","outcome":"A padronização é confundida com equidade e deixa de considerar necessidades individualizadas.","reason":"O respeito ético às pessoas exige atenção às demandas específicas e não uma trajetória idêntica para todos.","best":false},{"label":"Dispensar toda avaliação das necessidades psicossociais, pois qualquer pergunta sobre história e contexto poderia colocar a identidade de gênero em dúvida.","outcome":"A intenção de evitar discriminação resulta na perda de informações relevantes ao cuidado.","reason":"Uma avaliação respeitosa pode investigar contexto e necessidades sem patologizar ou questionar a identidade da pessoa.","best":false}]}],"wrapUp":"Este caso reforça acolhimento, autonomia, respeito à identidade de gênero e compreensão individualizada das demandas na P3."}],"tcc":[{"id":"esquema-vergonha","title":"Vergonha e esquema de defectividade","area":"Terapia do Esquema","intro":"Uma estudante evita pedir ajuda na faculdade porque imagina que os colegas descobrirão que ela é 'inferior'. Quando tira uma nota boa, atribui tudo à sorte.","stages":[{"prompt":"Que hipótese pode orientar a formulação inicial?","choices":[{"label":"Investigar experiências de desvalorização, crenças e estratégias de evitação.","outcome":"A análise começa a conectar história, situações atuais e modos de enfrentamento.","reason":"O esquema é hipótese clínica de padrão amplo, não diagnóstico a partir de uma frase.","best":true},{"label":"Investigar predominantemente um esquema de abandono, relacionando o pedido de ajuda ao medo de perder vínculos com os colegas.","outcome":"O foco recai na expectativa de ruptura do vínculo, pouco descrita no caso.","reason":"Abandono envolve medo de instabilidade ou perda de figuras significativas; o relato enfatiza inferioridade pessoal e desvalor.","best":false},{"label":"Examinar padrões inflexíveis de desempenho e a necessidade de atingir notas altas como explicação central.","outcome":"O trabalho se concentra em exigência por resultados, sem esclarecer por que o apoio dos colegas ameaça sua autoestima.","reason":"Padrões inflexíveis podem coexistir, mas a crença de ser defeituosa ou inferior é mais característica de defectividade/vergonha.","best":false}]},{"prompt":"Ela concorda que talvez seu pensamento seja rígido, mas ainda evita pedir ajuda. Como prosseguir?","choices":[{"label":"Trabalhar somente uma lista de evidências favoráveis às suas competências acadêmicas e reavaliar a crença antes de propor ações.","outcome":"O raciocínio verbal se amplia, mas a manutenção comportamental da esquiva fica menos testada.","reason":"A reestruturação cognitiva pode contribuir, mas a evitação persistente pede observação comportamental das previsões e consequências.","best":false},{"label":"Planejar um experimento gradual e observar o que realmente acontece.","outcome":"Ela reúne dados sobre o receio de ser julgada e testa alternativas.","reason":"Experimentos podem questionar manutenção da evitação e reforçar autonomia.","best":true},{"label":"Priorizar experiências imaginativas de acolhimento para reduzir vergonha antes de experimentar pedidos reais de ajuda.","outcome":"A intervenção aborda a história emocional, porém posterga o teste de previsões no contexto que mantém a esquiva.","reason":"Técnicas vivenciais podem integrar o plano; diante de uma previsão social específica e evitação atual, experimento graduado é mais informativo.","best":false}]}],"wrapUp":"A hipótese de esquema ajuda a pensar padrões, crenças e formas de enfrentamento; não reduz a pessoa a um rótulo."},{"id":"act-esquiva","title":"Evitação experiencial e valores","area":"ACT","intro":"Um universitário valoriza amizades, mas evita convites por receio de sentir ansiedade e passar vergonha. Quanto mais evita, menor fica sua vida social.","stages":[{"prompt":"O que é mais coerente com ACT?","choices":[{"label":"Identificar os pensamentos automáticos centrais e priorizar sua contestação para reduzir a ansiedade antes da ação.","outcome":"A análise é organizada ao redor da precisão das crenças, com menor atenção à função da esquiva.","reason":"A disputa do conteúdo cognitivo é típica de outras abordagens; na ACT, o foco está também na relação com a experiência e nas ações valorizadas.","best":false},{"label":"Investigar o custo da esquiva e identificar ações ligadas a valores.","outcome":"Ele percebe a tensão entre proteger-se do desconforto e cultivar vínculos.","reason":"A flexibilidade psicológica envolve agir com valores, mesmo na presença de emoções difíceis.","best":true},{"label":"Mapear situações temidas e construir uma hierarquia de exposição cuja meta principal seja diminuir os sintomas.","outcome":"O plano pode aumentar aproximação, mas define sucesso principalmente pela queda da ansiedade.","reason":"A exposição pode ser compatível com ACT; seu sentido nessa abordagem é ampliar flexibilidade e ação guiada por valores, não exigir alívio sintomático.","best":false}]},{"prompt":"Ele decide aceitar um convite, mas nota pensamentos de fracasso. Qual exercício poderia ajudar?","choices":[{"label":"Analisar se o pensamento de fracasso é empiricamente correto antes de decidir sobre a participação.","outcome":"A decisão passa a depender de refutar uma previsão, mantendo o pensamento no centro do controle da ação.","reason":"Desfusão não exige demonstrar que a ideia é falsa; busca reduzir seu domínio literal sobre o comportamento.","best":false},{"label":"Preparar técnicas de relaxamento para participar apenas se a ansiedade atingir um nível previamente aceitável.","outcome":"A participação é condicionada ao estado emocional e a negociação com o desconforto continua restrita.","reason":"Regular ativação pode ser útil, mas fazer da redução da ansiedade uma condição rígida perpetua evitação experiencial.","best":false},{"label":"Observar pensamentos como eventos mentais e escolher pequena ação alinhada ao valor.","outcome":"A pessoa se distancia da literalidade dos pensamentos sem precisar suprimi-los.","reason":"Desfusão cognitiva muda a relação com pensamentos e favorece ação comprometida.","best":true}]}],"wrapUp":"O foco da ACT é a relação com a experiência interna e a construção de uma vida coerente com valores."},{"id":"dbt-validacao","title":"Validação e mudança em uma crise emocional","area":"DBT","intro":"Uma pessoa relata grande sofrimento após uma discussão e diz que não consegue se acalmar. O profissional precisa acolher o relato e pensar em alternativas de resposta.","stages":[{"prompt":"Qual é a primeira intervenção que articula validação e mudança?","choices":[{"label":"Oferecer validação extensa e adiar o exame de comportamentos-problema até o sofrimento se estabilizar completamente.","outcome":"A pessoa se sente compreendida, mas a mudança comportamental fica indefinidamente postergada.","reason":"A DBT articula aceitação e mudança em vez de exigir que a crise emocional desapareça para trabalhar habilidades.","best":false},{"label":"Reconhecer o sofrimento e explorar habilidades concretas de regulação.","outcome":"A pessoa se sente escutada e pode considerar novas formas de agir.","reason":"DBT sustenta a dialética entre aceitação da experiência e mudança de comportamentos.","best":true},{"label":"Identificar prontamente a cadeia de comportamentos e apresentar alternativas de regulação antes de explorar o sentido vivido da emoção.","outcome":"A intervenção favorece análise funcional, mas corre o risco de enfraquecer a aliança por falta de validação.","reason":"A análise em cadeia é importante na DBT, porém sua efetividade depende de equilíbrio dialético com validação.","best":false}]},{"prompt":"Ela percebe o início de uma nova escalada emocional. Como trabalhar prevenção?","choices":[{"label":"Ensinar uma técnica de tolerância ao mal-estar como resposta padronizada, sem mapear os antecedentes da crise.","outcome":"A pessoa ganha um recurso prático, mas não diferencia situações que exigem prevenção ou outras habilidades.","reason":"Tolerância ao mal-estar é uma parte da DBT; a escolha da habilidade depende da cadeia de eventos e da função do comportamento.","best":false},{"label":"Reforçar principalmente a capacidade de descrever emoções e evitar planejar mudanças até desenvolver autoconsciência estável.","outcome":"Há avanço na nomeação da experiência, mas falta preparação para agir nos sinais iniciais de escalada.","reason":"Mindfulness ajuda a reconhecer sinais, mas prevenção também exige prática de habilidades e planejamento contextualizado.","best":false},{"label":"Identificar sinais, situações e habilidades praticáveis antes da crise.","outcome":"Ela elabora estratégias de enfrentamento para contextos futuros.","reason":"A análise funcional orienta prática de habilidades com propósito.","best":true}]}],"wrapUp":"A DBT combina validação, análise funcional e treinamento de habilidades sem reduzir a experiência humana à simples obediência."}],"meta":[{"id":"ego-conflitos","title":"O ego e seus três senhores","area":"Segunda tópica","intro":"Uma pessoa deseja reagir com hostilidade após uma ofensa, sente culpa antecipada por imaginar que isso seria errado e teme as consequências no trabalho.","stages":[{"prompt":"Como interpretar esse conflito no modelo freudiano?","choices":[{"label":"Localizar o conflito entre conteúdos conscientes e inconscientes, atribuindo ao ego a tarefa de tornar consciente o desejo do id.","outcome":"A formulação esclarece acessibilidade psíquica, mas reduz o conflito estrutural a uma divisão topográfica.","reason":"Na segunda tópica, id, ego e superego não correspondem diretamente aos sistemas consciente e inconsciente.","best":false},{"label":"Interpretar a culpa como resultado predominante do superego, considerando a realidade como fator secundário da decisão.","outcome":"A severidade moral é reconhecida, mas as exigências externas e pulsionais deixam de ser articuladas.","reason":"O ego media pressões do id, do superego e da realidade; privilegiar uma fonte pode empobrecer a formulação.","best":false},{"label":"Considerar as exigências do id, do superego e da realidade sobre o ego.","outcome":"O conflito passa a ser compreendido como tensão entre satisfação, censura e consequências.","reason":"O ego negocia exigências que podem ser simultaneamente incompatíveis.","best":true}]},{"prompt":"A pessoa evita o confronto, mas continua em conflito. O que pode explicar esse resultado?","choices":[{"label":"Investigar defesa, desejo e exigências internas sem assumir equivalência entre silêncio e resolução.","outcome":"A evitação pode reduzir tensão imediata sem elaborar o conflito.","reason":"A leitura dinâmica considera compromissos e defesas do ego.","best":true},{"label":"Compreender o silêncio como sinal de recalcamento já bem-sucedido, que resolveu temporariamente o conflito.","outcome":"A ausência de confronto é tomada como resolução interna, mesmo com sofrimento persistente.","reason":"Uma defesa pode reduzir manifestação consciente sem eliminar tensão entre exigências psíquicas.","best":false},{"label":"Atribuir o desconforto à severidade do superego e reduzir a função da realidade a desencadeante externo.","outcome":"A autocrítica é enfatizada, mas desejo e defesa permanecem pouco investigados.","reason":"O superego pode participar da culpa, porém a dinâmica exige examinar mediação, desejos e defesas.","best":false}]}],"wrapUp":"O caso serve para diferenciar instâncias, conflito, defesa e mediação das exigências na segunda tópica."},{"id":"pulsao-corpo","title":"Pulsão entre corpo e psiquismo","area":"Teoria das pulsões","intro":"Num seminário, colegas discutem por que Freud chamava a pulsão de conceito-limite entre o somático e o psíquico.","stages":[{"prompt":"Qual explicação é mais adequada?","choices":[{"label":"Uma necessidade fisiológica cuja descarga segue um objeto específico determinado pela fonte corporal.","outcome":"O fenômeno é entendido como necessidade biológica, com pouca explicação de destinos psíquicos.","reason":"A pulsão é conceito-limite; objeto é variável e não equivale a necessidade fisiológica com alvo determinado.","best":false},{"label":"Uma exigência de origem somática que se representa e busca destinos psíquicos.","outcome":"O grupo diferencia fonte corporal e organização psíquica da satisfação.","reason":"A pulsão inclui fonte, pressão, finalidade e objeto.","best":true},{"label":"Uma representação mental de prazer que surge como consequência secundária do reflexo orgânico.","outcome":"O plano mental é reduzido a efeito de resposta somática reflexa.","reason":"A pulsão impõe exigência de trabalho psíquico; não é mero reflexo nem se limita a representação consciente.","best":false}]},{"prompt":"Depois perguntam por que o objeto da pulsão pode variar. Como responder?","choices":[{"label":"Porque o objeto muda junto com a fonte somática e, por isso, cada alteração corporal redefine a pulsão.","outcome":"A variação é explicada pela fonte, confundindo dois componentes distintos.","reason":"Fonte remete ao processo somático; objeto é aquilo por meio do qual a finalidade pode ser alcançada.","best":false},{"label":"Porque diferentes finalidades pulsionais produzem objetos correspondentes, mesmo quando a fonte permanece a mesma.","outcome":"A resposta reconhece diversidade, mas trata finalidade e objeto como dependentes fixos.","reason":"A finalidade fundamental é satisfação; o objeto tem plasticidade e não é determinado univocamente por ela.","best":false},{"label":"Porque o objeto é meio de obtenção de satisfação, não uma fonte fixa biologicamente determinada.","outcome":"A turma diferencia objeto, fonte e finalidade.","reason":"O conceito permite plasticidade de investimentos libidinais.","best":true}]}],"wrapUp":"O caso revisa as quatro características da pulsão e a diferença entre pulsão e instinto."},{"id":"edipo-terceiro-identificacoes","title":"Triangulação edípica e identificação","area":"Complexo de Édipo","intro":"Uma criança pede atenção exclusiva de sua cuidadora. Aos poucos, percebe que ela mantém vínculos e compromissos com outras pessoas. A criança também começa a reconhecer algumas regras familiares mesmo sem a presença dos adultos.","stages":[{"prompt":"De acordo com a teoria freudiana, qual explicação ajuda a compreender a entrada de um terceiro nessa relação?","choices":[{"label":"A criança percebe vínculos que não dependem exclusivamente dela. Essa experiência introduz limites, diferenças e possibilidades de identificação, sem exigir um arranjo familiar único.","outcome":"A relação deixa de ser entendida como exclusiva e passa a incluir outras posições afetivas.","reason":"A triangulação edípica envolve função de terceiro, limites e identificações. A função não se restringe à figura do pai biológico.","best":true},{"label":"O conflito decorre apenas da presença física de três pessoas. Não é necessário considerar o significado afetivo que cada vínculo assume para a criança.","outcome":"A análise contabiliza pessoas, mas deixa de compreender o lugar que elas ocupam nas relações.","reason":"A triangulação não é simplesmente a presença simultânea de três indivíduos.","best":false},{"label":"A entrada do terceiro só pode ser reconhecida quando o pai biológico mora com a criança e impõe diretamente todas as regras da casa.","outcome":"A explicação reduz uma função relacional à composição biológica da família.","reason":"Na leitura psicanalítica, a função de terceiro pode ser exercida em diferentes configurações de cuidado.","best":false}]},{"prompt":"A criança passa a seguir algumas regras mesmo quando os cuidadores não estão presentes. Como relacionar essa situação à formação do superego?","choices":[{"label":"As identificações com figuras significativas podem contribuir para internalizar proibições e ideais. No modelo freudiano, esse processo participa da constituição do superego.","outcome":"As regras são entendidas como possíveis exigências internas, e não somente como ordens externas.","reason":"Freud relaciona a elaboração edípica e as identificações à formação do superego, sem reduzir o processo a uma cena isolada.","best":true},{"label":"A criança apenas memorizou regras de comportamento; por isso, a situação demonstra que a formação do superego não envolve identificações ou vínculos afetivos.","outcome":"A explicação reconhece a aprendizagem de regras, mas ignora sua possível internalização psíquica.","reason":"Memorizar normas não esgota a concepção freudiana da constituição do superego.","best":false},{"label":"O surgimento de uma regra interna mostra que o id passou a avaliar moralmente as próprias pulsões, tornando desnecessária a diferenciação entre id, ego e superego.","outcome":"A descrição mistura as funções das instâncias e torna difícil compreender a autocrítica.","reason":"No modelo estrutural de Freud, exigências morais e ideais são relacionados ao superego, não à função principal do id.","best":false}]}],"wrapUp":"Este caso articula triangulação, função de terceiro, identificação e formação do superego. São conceitos do roteiro P2, e não critérios para avaliar uma família real."}],"social":[{"id":"feed-polarizacao","title":"Dois feeds, duas realidades","area":"Algoritmos e Psicologia Social","intro":"Dois estudantes utilizam redes sociais com padrões de interação política muito diferentes. Depois de semanas, cada um afirma que 'todo mundo' apoia seu lado.","stages":[{"prompt":"Qual análise inicial é mais consistente?","choices":[{"label":"Atribuir a divergência principalmente ao viés individual de confirmação e usar o algoritmo apenas como meio de exibição.","outcome":"O efeito da seleção subjetiva é observado, mas a modulação de alcance e visibilidade fica em segundo plano.","reason":"Viés de confirmação ajuda a explicar escolhas; recomendação algorítmica participa também da exposição desigual de conteúdos.","best":false},{"label":"Concentrar a análise no grau de polarização afetiva já existente entre usuários antes de estudar os mecanismos dos feeds.","outcome":"Os vínculos partidários são examinados, mas a construção específica das experiências informacionais fica subanalisada.","reason":"Polarização pode anteceder o uso da plataforma; o caso pede integrar identidades, curadoria e práticas de engajamento.","best":false},{"label":"Investigar reforço algorítmico, identidade de grupo e viés de confirmação.","outcome":"Os estudantes percebem que visibilidade seletiva não equivale a consenso social.","reason":"O feed pode ampliar narrativas familiares e reduzir contato com perspectivas divergentes.","best":true}]},{"prompt":"Um deles encontra um post agressivo sobre o outro grupo. Qual atitude favorece análise crítica?","choices":[{"label":"Examinar a fonte, o enquadramento e por que o conteúdo foi recomendado.","outcome":"A mensagem pode ser avaliada sem compartilhamento imediato.","reason":"Desideologização exige questionar interesses, contexto e produção da narrativa.","best":true},{"label":"Comparar os dados de engajamento do post para estimar a intensidade real da atitude do grupo oposto.","outcome":"O interesse recai em métricas, mas curtidas e comentários não medem representatividade social diretamente.","reason":"Indicadores de plataforma são afetados por visibilidade e dinâmica de participação, não equivalem a amostra da população.","best":false},{"label":"Verificar a reputação da conta que publicou e usar o histórico de acertos como principal critério de confiança.","outcome":"A fonte é considerada, mas o enquadramento e a dinâmica de recomendação ficam pouco examinados.","reason":"Credibilidade requer análise de evidências e do contexto de circulação, não apenas confiança na identidade da conta.","best":false}]}],"wrapUp":"O foco da Psicologia Social é compreender como relações, mídia e identidades participam da construção de opiniões."},{"id":"fatalismo-contexto","title":"Fatalismo e participação comunitária","area":"Martín-Baró","intro":"Moradores de um bairro dizem que reclamar da falta de serviços não adianta porque 'sempre foi assim e nunca vai mudar'. Uma estudante tenta compreender esse discurso.","stages":[{"prompt":"Que leitura dialoga com Martín-Baró?","choices":[{"label":"Priorizar a identificação de crenças de baixa autoeficácia e propor estratégias individuais para aumentar a iniciativa.","outcome":"A sensação de impotência recebe atenção, mas sua produção histórica é tratada como fator lateral.","reason":"Martín-Baró relaciona fatalismo à realidade de opressão e ideologização, para além de crenças individuais.","best":false},{"label":"Interpretar a baixa participação como efeito da falta de vínculos comunitários e intervir primeiro na motivação para pertencer.","outcome":"A rede de apoio é considerada, mas barreiras materiais e relações de poder permanecem sem análise.","reason":"Pertencimento importa, porém a Psicologia da Libertação também examina impedimentos estruturais e histórias de resistência.","best":false},{"label":"Examinar obstáculos históricos e condições sociais que podem produzir sensação de impotência.","outcome":"O discurso deixa de ser visto como simples falha individual.","reason":"Fatalismo envolve experiências de desigualdade e relações de poder internalizadas.","best":true}]},{"prompt":"Algumas pessoas propõem ação coletiva. Como a análise pode avançar?","choices":[{"label":"Identificar possibilidades reais, redes de apoio e participação sem ignorar riscos e limites.","outcome":"O grupo relaciona consciência crítica a práticas sociais concretas.","reason":"Libertação articula ação, história e crítica da realidade vivida.","best":true},{"label":"Começar pela formação de lideranças locais para orientar uma pauta coletiva antes de levantar necessidades específicas.","outcome":"A mobilização pode ganhar organização, mas arrisca concentrar a voz em representantes.","reason":"A participação exige compreender experiências do grupo e possibilidades concretas, não apenas instituir condução externa.","best":false},{"label":"Organizar um encontro de sensibilização sobre direitos e avaliar a mudança pelas atitudes positivas relatadas.","outcome":"O acesso à informação é ampliado, mas transformações nas condições de participação não são verificadas.","reason":"Desideologização articula conhecimento histórico, ação coletiva e condições efetivas de participação.","best":false}]}],"wrapUp":"O caso conecta fatalismo, conscientização e ação situada sem responsabilizar vítimas pela desigualdade."},{"id":"marcadores-vida","title":"Desigualdade e pertencimento","area":"Marcadores sociais","intro":"Uma escola interpreta dificuldades de participação de estudantes de um grupo minoritário como desinteresse, sem examinar experiências de discriminação no ambiente.","stages":[{"prompt":"Qual pergunta social seria mais produtiva?","choices":[{"label":"Investigar a percepção de discriminação vivida por cada estudante e reunir relatos individuais por categoria social.","outcome":"A experiência subjetiva é valorizada, mas as práticas institucionais e a relação das categorias ficam menos visíveis.","reason":"Relatos importam, mas interseccionalidade examina processos de poder e não apenas somatório de experiências.","best":false},{"label":"Investigar experiências concretas, normas institucionais e relações de poder.","outcome":"A equipe encontra fatores de exclusão antes tratados como problemas individuais.","reason":"A análise psicossocial considera história, contexto e interseccionalidade.","best":true},{"label":"Comparar indicadores de desempenho escolar por grupo de pertencimento e atribuir as diferenças às identidades envolvidas.","outcome":"As disparidades aparecem, mas a análise corre o risco de naturalizá-las sem estudar produção institucional.","reason":"Marcadores sociais devem ser relacionados a estruturas e condições históricas, evitando causalidade identitária simples.","best":false}]},{"prompt":"Como começar uma intervenção respeitosa?","choices":[{"label":"Iniciar oficinas de sensibilização com equipe pedagógica antes de ouvir os estudantes para garantir uma abordagem tecnicamente uniforme.","outcome":"A instituição é mobilizada, mas as prioridades são escolhidas sem participação de quem vivencia o problema.","reason":"Práticas participativas precisam incluir sujeitos envolvidos na definição de problemas e caminhos.","best":false},{"label":"Criar indicadores agregados de clima escolar e utilizá-los como resposta suficiente, protegendo a identificação dos participantes.","outcome":"A confidencialidade é protegida, mas os números podem ocultar processos cotidianos que requerem escuta e intervenção.","reason":"Dados agregados ajudam, porém não substituem análise institucional e participação dos estudantes.","best":false},{"label":"Escutar os próprios estudantes, examinar práticas da escola e construir ações com participação.","outcome":"As medidas se aproximam das experiências de quem vive o problema.","reason":"Processos participativos evitam impor respostas externas sem contexto.","best":true}]}],"wrapUp":"O caso mostra que a Psicologia Social trabalha pertencimento e instituições, não só características individuais."}],"grupos":[{"id":"grupos-filme-eva-tribunal","title":"Eva no tribunal","area":"Moreno — espontaneidade e conserva cultural","intro":"Cena: no tribunal, Eva decide identificar o verdadeiro responsável pelo crime, contrariando a expectativa de proteger Paco. A resposta rompe uma lealdade rígida e considera as consequências para o inocente.","stages":[{"prompt":"Como o depoimento de Eva ilustra espontaneidade?","choices":[{"label":"Espontaneidade: uma nova resposta adequada, rompendo o padrão de lealdade rígida.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"Ela encontra uma resposta nova e adequada diante de uma situação marcada por expectativas antigas de lealdade. Não se trata de agir por impulso."},{"label":"Sociometria: a decisão representa um levantamento das preferências entre colegas.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Ela encontra uma resposta nova e adequada diante de uma situação marcada por expectativas antigas de lealdade. Não se trata de agir por impulso."},{"label":"Aquecimento: o depoimento prepara uma dramatização psicodramática.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Ela encontra uma resposta nova e adequada diante de uma situação marcada por expectativas antigas de lealdade. Não se trata de agir por impulso."}]},{"prompt":"Cena: Eva aprende, em seu grupo de pertencimento, que deve defender os seus mesmo diante de uma injustiça. Essa regra condiciona o depoimento esperado dela.\n\nO que a regra de lealdade ilustra para Moreno?","choices":[{"label":"A obrigação é um sociograma das relações de Eva.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Uma conserva cultural: um padrão transmitido e cristalizado que, quando rigidamente repetido, limita respostas novas. A lealdade em si não é necessariamente prejudicial."},{"label":"A obrigação aprendida de proteger o próprio grupo pode funcionar como conserva cultural.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"Uma conserva cultural: um padrão transmitido e cristalizado que, quando rigidamente repetido, limita respostas novas. A lealdade em si não é necessariamente prejudicial."},{"label":"A obrigação é uma técnica de inversão de papéis.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Uma conserva cultural: um padrão transmitido e cristalizado que, quando rigidamente repetido, limita respostas novas. A lealdade em si não é necessariamente prejudicial."}]}],"wrapUp":"Ela encontra uma resposta nova e adequada diante de uma situação marcada por expectativas antigas de lealdade. Não se trata de agir por impulso. Uma conserva cultural: um padrão transmitido e cristalizado que, quando rigidamente repetido, limita respostas novas. A lealdade em si não é necessariamente prejudicial."},{"id":"grupos-filme-marcus-mae","title":"Marcus e a mãe","area":"Moreno — papéis e átomo social","intro":"Cena: Marcus procura a mãe e manifesta o desejo de retornar para casa. Sua relação como filho volta a ocupar espaço ao lado de outras possibilidades de vida.","stages":[{"prompt":"Como a história de Marcus ajuda a compreender a teoria dos papéis?","choices":[{"label":"A cena é uma inversão de papéis conduzida por um diretor.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Os papéis existem nas relações e podem se reorganizar. O papel ligado à gangue não esgota a identidade de Marcus; ele pode reconstruir a relação como filho."},{"label":"A reorganização dos papéis permite reconstruir a relação como filho.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"Os papéis existem nas relações e podem se reorganizar. O papel ligado à gangue não esgota a identidade de Marcus; ele pode reconstruir a relação como filho."},{"label":"O papel de filho é uma identidade fixa que exclui todos os demais papéis.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Os papéis existem nas relações e podem se reorganizar. O papel ligado à gangue não esgota a identidade de Marcus; ele pode reconstruir a relação como filho."}]},{"prompt":"Cena: Marcus está afastado da mãe e vinculado a colegas da gangue; quando busca a mãe e se aproxima da turma, sua rede significativa se reorganiza. Trata-se de uma leitura conceitual, não de um levantamento formal.\n\nO que significa átomo social?","choices":[{"label":"Átomo social é a lista de todos os colegas presentes na aula.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"É o conjunto de relações afetivamente significativas que situam a pessoa em sua rede social. A análise considera vínculos, proximidades e distâncias."},{"label":"Átomo social é o palco físico onde se dramatiza.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"É o conjunto de relações afetivamente significativas que situam a pessoa em sua rede social. A análise considera vínculos, proximidades e distâncias."},{"label":"A aproximação da mãe pode representar transformação de uma relação significativa do átomo social.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"É o conjunto de relações afetivamente significativas que situam a pessoa em sua rede social. A análise considera vínculos, proximidades e distâncias."}]}],"wrapUp":"Os papéis existem nas relações e podem se reorganizar. O papel ligado à gangue não esgota a identidade de Marcus; ele pode reconstruir a relação como filho. É o conjunto de relações afetivamente significativas que situam a pessoa em sua rede social. A análise considera vínculos, proximidades e distâncias."},{"id":"grupos-filme-linha-moreno","title":"O jogo da linha","area":"Moreno — aquecimento e sociometria","intro":"Cena: no jogo da linha, Erin começa com perguntas cotidianas e gradualmente aborda vivências significativas. Movimento, participação e reconhecimento mútuo mobilizam a turma. É uma analogia com o aquecimento, não uma sessão formal.","stages":[{"prompt":"Em que sentido a dinâmica da linha se aproxima do aquecimento inespecífico?","choices":[{"label":"Dramatização formal de um conflito individual com ego auxiliar.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Ela mobiliza o grupo por meio da ação e favorece a disponibilidade para reconhecer experiências comuns. O aquecimento específico prepararia um tema e uma cena para dramatização."},{"label":"Inversão de papéis porque todos trocam de lado da sala.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Ela mobiliza o grupo por meio da ação e favorece a disponibilidade para reconhecer experiências comuns. O aquecimento específico prepararia um tema e uma cena para dramatização."},{"label":"Mobilização corporal e relacional, semelhante à função do aquecimento inespecífico.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"Ela mobiliza o grupo por meio da ação e favorece a disponibilidade para reconhecer experiências comuns. O aquecimento específico prepararia um tema e uma cena para dramatização."}]},{"prompt":"Cena: no começo, a turma se distribui segundo pertencimentos e rivalidades. É possível observar aproximações e rejeições, mas não há um teste sociométrico com critério de escolha explícito.\n\nO que seria necessário para investigar sociometricamente os vínculos da turma?","choices":[{"label":"Um teste sociométrico exigiria escolhas feitas segundo critério explícito e análise da rede.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"Definir um critério concreto de escolha, como com quem realizar uma tarefa, coletar escolhas dos participantes e analisar reciprocidades e rejeições. A disposição das carteiras não basta."},{"label":"Ficar na linha equivale a escolher com quem realizar uma tarefa.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Definir um critério concreto de escolha, como com quem realizar uma tarefa, coletar escolhas dos participantes e analisar reciprocidades e rejeições. A disposição das carteiras não basta."},{"label":"A atividade por si só produz um sociograma completo.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Definir um critério concreto de escolha, como com quem realizar uma tarefa, coletar escolhas dos participantes e analisar reciprocidades e rejeições. A disposição das carteiras não basta."}]}],"wrapUp":"Ela mobiliza o grupo por meio da ação e favorece a disponibilidade para reconhecer experiências comuns. O aquecimento específico prepararia um tema e uma cena para dramatização. Definir um critério concreto de escolha, como com quem realizar uma tarefa, coletar escolhas dos participantes e analisar reciprocidades e rejeições. A disposição das carteiras não basta."},{"id":"grupos-filme-diarios-rogers","title":"Os diários da turma","area":"Rogers — aceitação e material pessoal","intro":"Cena: Erin distribui diários e permite que os alunos decidam se a professora poderá lê-los. Ela acolhe as experiências independentemente de elas corresponderem a expectativas escolares.","stages":[{"prompt":"Como os diários ilustram consideração positiva incondicional?","choices":[{"label":"Consideração positiva incondicional e respeito à escolha de compartilhar.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"O valor da pessoa não depende da aprovação de seu relato ou de seu desempenho. O espaço de expressão respeita autonomia, sem significar aprovação de condutas violentas."},{"label":"Congruência exige que todos revelem o conteúdo dos diários.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"O valor da pessoa não depende da aprovação de seu relato ou de seu desempenho. O espaço de expressão respeita autonomia, sem significar aprovação de condutas violentas."},{"label":"Aceitação positiva significa aprovar toda ação narrada.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"O valor da pessoa não depende da aprovação de seu relato ou de seu desempenho. O espaço de expressão respeita autonomia, sem significar aprovação de condutas violentas."}]},{"prompt":"Cena: os relatos dos diários tratam de perdas, violência, moradia e relações familiares, dando lugar à história particular dos estudantes.\n\nComo a escrita favorece a exploração de material pessoal?","choices":[{"label":"Feedback interpessoal formal, porque a professora recebe textos.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Ela permite organizar e expressar experiências que possuem significado para quem escreve, respeitando o ritmo e a decisão de compartilhar."},{"label":"Exploração de experiências de significado pessoal sem obrigar a exposição.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"Ela permite organizar e expressar experiências que possuem significado para quem escreve, respeitando o ritmo e a decisão de compartilhar."},{"label":"Milling around, porque escrever é sempre uma conversa superficial.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Ela permite organizar e expressar experiências que possuem significado para quem escreve, respeitando o ritmo e a decisão de compartilhar."}]}],"wrapUp":"O valor da pessoa não depende da aprovação de seu relato ou de seu desempenho. O espaço de expressão respeita autonomia, sem significar aprovação de condutas violentas. Ela permite organizar e expressar experiências que possuem significado para quem escreve, respeitando o ritmo e a decisão de compartilhar."},{"id":"grupos-filme-eva-anne","title":"Eva e o diário de Anne Frank","area":"Rogers — sentimentos negativos e empatia","intro":"Cena: Eva termina a leitura do diário de Anne Frank e questiona Erin, revoltada com a morte da personagem. A reação dá lugar a uma conversa com a turma sobre a história.","stages":[{"prompt":"Qual processo rogeriano aparece na revolta de Eva?","choices":[{"label":"A professora deve evitar a divergência para preservar aceitação.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Expressão de sentimentos negativos no aqui-agora, inclusive dirigidos à facilitadora. A manifestação pode ser acolhida e elaborada sem retaliação."},{"label":"Expressão de sentimentos negativos no aqui-agora, inclusive dirigidos à professora.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"Expressão de sentimentos negativos no aqui-agora, inclusive dirigidos à facilitadora. A manifestação pode ser acolhida e elaborada sem retaliação."},{"label":"A reação demonstra ausência de qualquer confiança no grupo.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"Expressão de sentimentos negativos no aqui-agora, inclusive dirigidos à facilitadora. A manifestação pode ser acolhida e elaborada sem retaliação."}]},{"prompt":"Cena: os estudantes visitam o museu do Holocausto e escutam sobreviventes em um jantar. Podem compreender experiências de pessoas de outro contexto histórico sem afirmar que suas histórias são idênticas.\n\nComo o encontro com os sobreviventes ilustra compreensão empática?","choices":[{"label":"Empatia exige ter passado pela mesma experiência.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"A escuta procura compreender o vivido do outro a partir da perspectiva dele, reconhecendo sofrimentos e diferenças sem reduzir uma experiência à outra."},{"label":"Empatia implica concordar com toda interpretação de Eva.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"A escuta procura compreender o vivido do outro a partir da perspectiva dele, reconhecendo sofrimentos e diferenças sem reduzir uma experiência à outra."},{"label":"Compreensão empática implica escutar o referencial do outro sem presumir vivências idênticas.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"A escuta procura compreender o vivido do outro a partir da perspectiva dele, reconhecendo sofrimentos e diferenças sem reduzir uma experiência à outra."}]}],"wrapUp":"Expressão de sentimentos negativos no aqui-agora, inclusive dirigidos à facilitadora. A manifestação pode ser acolhida e elaborada sem retaliação. A escuta procura compreender o vivido do outro a partir da perspectiva dele, reconhecendo sofrimentos e diferenças sem reduzir uma experiência à outra."},{"id":"grupos-filme-brinde-miep","title":"Do brinde à iniciativa coletiva","area":"Rogers — fachadas e autonomia","intro":"Cena: no brinde à mudança, um aluno compartilha o relato de que perdeu a moradia e teve vergonha de voltar à escola. Revela uma vulnerabilidade antes escondida.","stages":[{"prompt":"Como essa cena ilustra o estalar das fachadas?","choices":[{"label":"A exposição pública é obrigatória para criar autenticidade.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"A segurança relacional permite reduzir defesas e apresentar experiências pessoais que antes eram ocultadas. O grupo passa a conhecer a pessoa além de sua imagem defensiva."},{"label":"O relato é uma técnica psicodramática de espelho.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"A segurança relacional permite reduzir defesas e apresentar experiências pessoais que antes eram ocultadas. O grupo passa a conhecer a pessoa além de sua imagem defensiva."},{"label":"Estalar das fachadas: uma experiência antes escondida é compartilhada em um ambiente mais seguro.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"A segurança relacional permite reduzir defesas e apresentar experiências pessoais que antes eram ocultadas. O grupo passa a conhecer a pessoa além de sua imagem defensiva."}]},{"prompt":"Cena: os alunos propõem convidar Miep Gies e arrecadar recursos. Erin apoia a iniciativa em vez de se colocar como única autora do projeto.\n\nComo a iniciativa de convidar Miep Gies ilustra facilitação e autonomia?","choices":[{"label":"A proposta de convidar Miep Gies mostra protagonismo e autonomia apoiados pela professora.","best":true,"outcome":"A relação reconhece o conceito e o contexto concreto.","reason":"A facilitadora oferece condições para que o grupo desenvolva iniciativas próprias e participe das decisões. A professora continua responsável pela atividade escolar."},{"label":"Facilitação exige que a professora decida tudo previamente.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"A facilitadora oferece condições para que o grupo desenvolva iniciativas próprias e participe das decisões. A professora continua responsável pela atividade escolar."},{"label":"O projeto transforma automaticamente a turma em grupo de encontro clínico.","best":false,"outcome":"Essa leitura confunde conceitos ou atribui ao filme algo que não foi demonstrado.","reason":"A facilitadora oferece condições para que o grupo desenvolva iniciativas próprias e participe das decisões. A professora continua responsável pela atividade escolar."}]}],"wrapUp":"A segurança relacional permite reduzir defesas e apresentar experiências pessoais que antes eram ocultadas. O grupo passa a conhecer a pessoa além de sua imagem defensiva. A facilitadora oferece condições para que o grupo desenvolva iniciativas próprias e participe das decisões. A professora continua responsável pela atividade escolar."}]};
